insert into public.content_sources (source_type,title,issuer,url,status,notes) values
('outro','Prova objetiva PF - Papiloscopista - 2021','Polícia Federal / CEBRASPE','https://www.gov.br/pf/pt-br/acesso-a-informacao/servidores/concursos/provas-e-gabaritos-de-concursos-anteriores/concurso-carreira-policial-2021/papiloscopista-policial-federal/prova_cargo_4_papiloscopista_policial_federal.pdf/view','vigente','Caderno oficial usado para extração auditável de itens (Google Drive fileId 1KbXyqwbK3-g27fCgxmQ2gzeJ7-DONF7v, texto lido verbatim nesta sessão).'),
('outro','Gabarito definitivo PF - Papiloscopista - 2021','Polícia Federal / CEBRASPE','https://www.gov.br/pf/pt-br/acesso-a-informacao/servidores/concursos/provas-e-gabaritos-de-concursos-anteriores/concurso-carreira-policial-2021/papiloscopista-policial-federal/gab_definitivo_ppf.pdf/view','vigente','Gabarito oficial definitivo Matriz_577_PF_004_00, explicitamente rotulado CARGO: PAPILOSCOPISTA POLICIAL FEDERAL (Google Drive fileId 1a4uF_zzQnp4ijZupXQen_H0BIY9a9aZB); X identifica item anulado.')
