-- New syllabus edition for this career.
insert into public.syllabus_editions (contest_name,role_name,contest_year,source_id)
select 'Polícia Federal','Papiloscopista Policial Federal',2021,(select id from public.content_sources where url=$q$https://www.gov.br/pf/pt-br/acesso-a-informacao/servidores/concursos/provas-e-gabaritos-de-concursos-anteriores/concurso-carreira-policial-2021/papiloscopista-policial-federal/prova_cargo_4_papiloscopista_policial_federal.pdf/view$q$)
where not exists (
  select 1 from public.syllabus_editions
  where contest_name='Polícia Federal' and role_name='Papiloscopista Policial Federal' and contest_year=2021
);

-- Discipline breakdown derived directly from reading the prova's own item
-- text (command blocks and subject matter): Língua Portuguesa (1-18, two
-- reading-comprehension texts shared with other cargos of this concurso),
-- Redação Oficial (19-24), Direito Administrativo (25-27), Direito
-- Constitucional (28-30), Direito Penal e Processual Penal (31-33),
-- Legislação Penal Especial (34-36), Estatística e Probabilidade (37-48),
-- Raciocínio Lógico-Matemático (49-60), Informática (61-96, a much larger
-- block than in Delegado/Escrivão, spanning Internet/intranet, redes,
-- segurança, cloud computing, teoria geral de sistemas, mineração de
-- dados/bigdata, modelagem e bancos de dados, programação Python/R e API),
-- and, distinctively for this cargo, the "Conhecimentos Específicos" block
-- of natural sciences applied to papiloscopia/perícia: Biologia (97-104:
-- composição química da matéria viva, organelas, placenta, vias
-- metabólicas, gemelaridade/DNA), Física (105-112: ondas, eletrostática,
-- óptica) and Química (113-120: tabela periódica, entalpia de dissolução,
-- óxido de ferro(III) usado na revelação de impressões digitais, equilíbrio
-- químico, interações intermoleculares — directly tied to the fingerprint
-- (papiloscopia) identification techniques named in items 113-120's own
-- prompt text).
with edition as (
  select id from public.syllabus_editions
  where contest_name='Polícia Federal' and role_name='Papiloscopista Policial Federal' and contest_year=2021
)
insert into public.syllabus_topics (edition_id,block_name,discipline,topic_order,topic_text,content_status)
select edition.id,'Prova objetiva',d.discipline,1,d.topic_text,'current'
from edition cross join (values
  ('Língua Portuguesa','Compreensão e interpretação de textos; tipologia textual; aspectos linguísticos: coesão e coerência, morfossintaxe, reescrita de frases e pontuação.'),
  ('Redação Oficial','Manual de Redação da Presidência da República: e-mail como documento oficial, exposição de motivos, pronomes de tratamento, grafia de datas, vocativos e padrão ofício.'),
  ('Direito Administrativo','Sigilo funcional, poder de polícia administrativo e controle da administração pública sobre o regime disciplinar do servidor público.'),
  ('Direito Constitucional','Competência constitucional da Polícia Federal (art. 144 da CF), crimes inafiançáveis e extradição de brasileiro naturalizado (art. 5º da CF).'),
  ('Direito Penal e Processual Penal','Cadeia de custódia da prova, consumação do crime de descaminho e flagrante preparado.'),
  ('Legislação Penal Especial','Lei de Abuso de Autoridade, extradição e prescrição segundo a lei brasileira, e acesso ao Banco Nacional Multibiométrico e de Impressões Digitais.'),
  ('Estatística e Probabilidade','Variáveis aleatórias contínuas, distribuições conjuntas, estimação de parâmetros e regressão linear simples.'),
  ('Raciocínio Lógico-Matemático','Análise combinatória, lógica proposicional (equivalência, negação, tabela-verdade, validade de argumentos) e teoria dos conjuntos.'),
  ('Informática','Internet e intranet, redes de computadores, segurança da informação, computação em nuvem, teoria geral de sistemas, dados/informação/conhecimento/inteligência, mineração de dados e bigdata, modelagem conceitual, banco de dados, dados estruturados, SQL, programação (Python e R) e API.'),
  ('Biologia Aplicada à Papiloscopia','Composição química da matéria viva, componentes citoplasmáticos de células eucarióticas, placenta, vias metabólicas e gemelaridade/DNA aplicados à identificação humana.'),
  ('Física Aplicada à Papiloscopia','Ondas estacionárias, eletrostática de distribuições de carga não uniformes e óptica geométrica e ondulatória.'),
  ('Química Aplicada à Papiloscopia','Tabela periódica, entalpia de dissolução, reações do óxido de ferro (III) usado na revelação de impressões digitais, equilíbrio químico e interações intermoleculares.')
) d(discipline,topic_text)
on conflict (edition_id,discipline,topic_order) do update set topic_text=excluded.topic_text;

with imported(exam_year,item_number,subject,question_text,raw_extraction,official_answer,source_page,content_status,legal_review_required,context_review_required,review_note) as (values
(2021,1,$q$Língua Portuguesa$q$,$q$Infere-se do texto que a personagem, ao longo de toda a narrativa, está sendo tomada por um tipo de nostalgia que não está relacionada ao espaço físico, mas, sim, a uma saudade de um estado — o da primeira paixão.$q$,$q$Infere-se do texto que a personagem, ao longo de toda a narrativa, está sendo tomada por um tipo de nostalgia que não está relacionada ao espaço físico, mas, sim, a uma saudade de um estado — o da primeira paixão.$q$,'E',1,'under_review',true,false,$q$Transcrição verbatim do caderno de provas Cargo 4 - Papiloscopista Policial Federal (PF 2021); gabarito conferido em Matriz_577_PF_004_00 (cargo Papiloscopista). Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2021,2,$q$Língua Portuguesa$q$,$q$O vocábulo “até” (sétimo período do primeiro parágrafo), empregado no sentido de inclusive, poderia ser deslocado para o início do trecho “com alegria até”.$q$,$q$O vocábulo “até” (sétimo período do primeiro parágrafo), empregado no sentido de inclusive, poderia ser deslocado para o início do trecho “com alegria até”.$q$,'C',1,'under_review',true,false,$q$Transcrição verbatim do caderno de provas Cargo 4 - Papiloscopista Policial Federal (PF 2021); gabarito conferido em Matriz_577_PF_004_00 (cargo Papiloscopista). Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2021,3,$q$Língua Portuguesa$q$,$q$O termo “ali” (quinto período do segundo parágrafo) refere-se a “aquela casa” (primeiro período do texto).$q$,$q$O termo “ali” (quinto período do segundo parágrafo) refere-se a “aquela casa” (primeiro período do texto).$q$,'E',1,'under_review',true,false,$q$Transcrição verbatim do caderno de provas Cargo 4 - Papiloscopista Policial Federal (PF 2021); gabarito conferido em Matriz_577_PF_004_00 (cargo Papiloscopista). Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2021,4,$q$Língua Portuguesa$q$,$q$Os vocábulos “Claro” e “arejado” (ao final do primeiro parágrafo) fazem referência a “navio”, vocábulo que os antecede no período anterior.$q$,$q$Os vocábulos “Claro” e “arejado” (ao final do primeiro parágrafo) fazem referência a “navio”, vocábulo que os antecede no período anterior.$q$,'E',1,'under_review',true,false,$q$Transcrição verbatim do caderno de provas Cargo 4 - Papiloscopista Policial Federal (PF 2021); gabarito conferido em Matriz_577_PF_004_00 (cargo Papiloscopista). Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2021,5,$q$Língua Portuguesa$q$,$q$Sem prejuízo para o sentido original do texto, o período “Quando anoitecia, toda aquela vizinhança começava, ao mesmo tempo, a fazer bife, e o ar ficava cheirando a cebola e alho” poderia ser reescrito da seguinte maneira: Ao anoitecer, toda aquela vizinhança começava a fazer bife e o ar ficava cheirando à cebola e alho ao mesmo tempo.$q$,$q$Sem prejuízo para o sentido original do texto, o período “Quando anoitecia, toda aquela vizinhança começava, ao mesmo tempo, a fazer bife, e o ar ficava cheirando a cebola e alho” poderia ser reescrito da seguinte maneira: Ao anoitecer, toda aquela vizinhança começava a fazer bife e o ar ficava cheirando à cebola e alho ao mesmo tempo.$q$,'E',1,'under_review',true,false,$q$Transcrição verbatim do caderno de provas Cargo 4 - Papiloscopista Policial Federal (PF 2021); gabarito conferido em Matriz_577_PF_004_00 (cargo Papiloscopista). Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2021,6,$q$Língua Portuguesa$q$,$q$No sétimo período do primeiro parágrafo, a forma “lhe” desempenha a função de complemento indireto da forma verbal “mostrasse” e funciona como elemento de coesão ao retomar o personagem da narrativa.$q$,$q$No sétimo período do primeiro parágrafo, a forma “lhe” desempenha a função de complemento indireto da forma verbal “mostrasse” e funciona como elemento de coesão ao retomar o personagem da narrativa.$q$,'C',1,'under_review',true,false,$q$Transcrição verbatim do caderno de provas Cargo 4 - Papiloscopista Policial Federal (PF 2021); gabarito conferido em Matriz_577_PF_004_00 (cargo Papiloscopista). Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2021,7,$q$Língua Portuguesa$q$,$q$A forma verbal “tinha” foi empregada com o mesmo sentido nas duas ocorrências nos seguintes períodos do segundo parágrafo: “Mas tinha a gaveta. Tinha de desocupar aquela gaveta.”.$q$,$q$A forma verbal “tinha” foi empregada com o mesmo sentido nas duas ocorrências nos seguintes períodos do segundo parágrafo: “Mas tinha a gaveta. Tinha de desocupar aquela gaveta.”.$q$,'E',1,'under_review',true,false,$q$Transcrição verbatim do caderno de provas Cargo 4 - Papiloscopista Policial Federal (PF 2021); gabarito conferido em Matriz_577_PF_004_00 (cargo Papiloscopista). Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2021,8,$q$Língua Portuguesa$q$,$q$Na oração “Cabia tudo em uma mala só”, o vocábulo “tudo” exerce a função de sujeito.$q$,$q$Na oração “Cabia tudo em uma mala só”, o vocábulo “tudo” exerce a função de sujeito.$q$,'C',1,'under_review',true,false,$q$Transcrição verbatim do caderno de provas Cargo 4 - Papiloscopista Policial Federal (PF 2021); gabarito conferido em Matriz_577_PF_004_00 (cargo Papiloscopista). Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2021,9,$q$Língua Portuguesa$q$,$q$Conclui-se das ideias do texto que, apesar de existirem peculiaridades culturais e históricas sobre o estabelecimento das penas em cada país, o crescimento do encarceramento apresenta-se como um fenômeno universal que, chancelado pela opinião pública, tem sido adotado como política de segurança por muitos governos, principalmente os das regiões mais desenvolvidas do mundo.$q$,$q$Conclui-se das ideias do texto que, apesar de existirem peculiaridades culturais e históricas sobre o estabelecimento das penas em cada país, o crescimento do encarceramento apresenta-se como um fenômeno universal que, chancelado pela opinião pública, tem sido adotado como política de segurança por muitos governos, principalmente os das regiões mais desenvolvidas do mundo.$q$,'C',1,'under_review',true,false,$q$Transcrição verbatim do caderno de provas Cargo 4 - Papiloscopista Policial Federal (PF 2021); gabarito conferido em Matriz_577_PF_004_00 (cargo Papiloscopista). Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2021,10,$q$Língua Portuguesa$q$,$q$Seriam preservados a correção gramatical e os sentidos do texto caso a vírgula empregada imediatamente após o vocábulo “rapidamente” (primeiro período do texto) fosse suprimida.$q$,$q$Seriam preservados a correção gramatical e os sentidos do texto caso a vírgula empregada imediatamente após o vocábulo “rapidamente” (primeiro período do texto) fosse suprimida.$q$,'E',1,'under_review',true,false,$q$Transcrição verbatim do caderno de provas Cargo 4 - Papiloscopista Policial Federal (PF 2021); gabarito conferido em Matriz_577_PF_004_00 (cargo Papiloscopista). Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2021,11,$q$Língua Portuguesa$q$,$q$No segundo período do texto, a partícula “se” classifica-se como partícula apassivadora.$q$,$q$No segundo período do texto, a partícula “se” classifica-se como partícula apassivadora.$q$,'E',1,'under_review',true,false,$q$Transcrição verbatim do caderno de provas Cargo 4 - Papiloscopista Policial Federal (PF 2021); gabarito conferido em Matriz_577_PF_004_00 (cargo Papiloscopista). Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2021,12,$q$Língua Portuguesa$q$,$q$Conclui-se do trecho ‘há uma crescente necessidade de disciplinar importantes grupos e segmentos populacionais’ que os grupos populacionais a serem disciplinados são compostos por pessoas que têm autoridade e gozam de prestígio na sociedade, do que se infere que tais grupos têm adotado comportamentos indesejáveis.$q$,$q$Conclui-se do trecho ‘há uma crescente necessidade de disciplinar importantes grupos e segmentos populacionais’ que os grupos populacionais a serem disciplinados são compostos por pessoas que têm autoridade e gozam de prestígio na sociedade, do que se infere que tais grupos têm adotado comportamentos indesejáveis.$q$,'E',1,'under_review',true,false,$q$Transcrição verbatim do caderno de provas Cargo 4 - Papiloscopista Policial Federal (PF 2021); gabarito conferido em Matriz_577_PF_004_00 (cargo Papiloscopista). Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2021,13,$q$Língua Portuguesa$q$,$q$A forma verbal “crescem” (terceiro período do primeiro parágrafo) está flexionada no plural para concordar com o sujeito composto cujos núcleos são “gastos”, “efetivos” e “serviços”.$q$,$q$A forma verbal “crescem” (terceiro período do primeiro parágrafo) está flexionada no plural para concordar com o sujeito composto cujos núcleos são “gastos”, “efetivos” e “serviços”.$q$,'E',1,'under_review',true,false,$q$Transcrição verbatim do caderno de provas Cargo 4 - Papiloscopista Policial Federal (PF 2021); gabarito conferido em Matriz_577_PF_004_00 (cargo Papiloscopista). Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2021,14,$q$Língua Portuguesa$q$,$q$O travessão empregado no último período do primeiro parágrafo confere ao trecho final do período, por ele isolado, um destaque, mas sua supressão manteria a correção gramatical do texto.$q$,$q$O travessão empregado no último período do primeiro parágrafo confere ao trecho final do período, por ele isolado, um destaque, mas sua supressão manteria a correção gramatical do texto.$q$,'C',1,'under_review',true,false,$q$Transcrição verbatim do caderno de provas Cargo 4 - Papiloscopista Policial Federal (PF 2021); gabarito conferido em Matriz_577_PF_004_00 (cargo Papiloscopista). Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2021,15,$q$Língua Portuguesa$q$,$q$Seria mantida a correção gramatical do texto caso a forma verbal “esperam” (primeiro período do texto) fosse substituída por espera.$q$,$q$Seria mantida a correção gramatical do texto caso a forma verbal “esperam” (primeiro período do texto) fosse substituída por espera.$q$,'C',1,'under_review',true,false,$q$Transcrição verbatim do caderno de provas Cargo 4 - Papiloscopista Policial Federal (PF 2021); gabarito conferido em Matriz_577_PF_004_00 (cargo Papiloscopista). Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2021,16,$q$Língua Portuguesa$q$,$q$Na argumentação desenvolvida no texto, a informação presente em “Cresce rapidamente em quase todos os países o número de pessoas na prisão” (primeiro período do texto) coaduna-se com a informação presente em “o rápido crescimento parece ser um fenômeno universal em toda a ponta ‘mais desenvolvida’ do mundo” (final do último parágrafo do texto).$q$,$q$Na argumentação desenvolvida no texto, a informação presente em “Cresce rapidamente em quase todos os países o número de pessoas na prisão” (primeiro período do texto) coaduna-se com a informação presente em “o rápido crescimento parece ser um fenômeno universal em toda a ponta ‘mais desenvolvida’ do mundo” (final do último parágrafo do texto).$q$,'C',1,'under_review',true,false,$q$Transcrição verbatim do caderno de provas Cargo 4 - Papiloscopista Policial Federal (PF 2021); gabarito conferido em Matriz_577_PF_004_00 (cargo Papiloscopista). Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2021,17,$q$Língua Portuguesa$q$,$q$A palavra “idiossincrasias” (segundo parágrafo) poderia ser substituída por compatibilidades sem prejuízo para a correção gramatical e para os sentidos do texto.$q$,$q$A palavra “idiossincrasias” (segundo parágrafo) poderia ser substituída por compatibilidades sem prejuízo para a correção gramatical e para os sentidos do texto.$q$,'E',1,'under_review',true,false,$q$Transcrição verbatim do caderno de provas Cargo 4 - Papiloscopista Policial Federal (PF 2021); gabarito conferido em Matriz_577_PF_004_00 (cargo Papiloscopista). Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2021,18,$q$Língua Portuguesa$q$,$q$As palavras “intensamente”, em “Em quase toda parte, a rede de prisões está se ampliando intensamente”, e “ampliada”, em “e sugere uma ‘significação muito ampliada da solução institucional como componente da política criminal’” desempenham a mesma função sintática nos períodos em que ocorrem.$q$,$q$As palavras “intensamente”, em “Em quase toda parte, a rede de prisões está se ampliando intensamente”, e “ampliada”, em “e sugere uma ‘significação muito ampliada da solução institucional como componente da política criminal’” desempenham a mesma função sintática nos períodos em que ocorrem.$q$,'E',1,'under_review',true,false,$q$Transcrição verbatim do caderno de provas Cargo 4 - Papiloscopista Policial Federal (PF 2021); gabarito conferido em Matriz_577_PF_004_00 (cargo Papiloscopista). Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2021,19,$q$Redação Oficial$q$,$q$Quando da redação de e-mail que possa ser considerado um documento oficial, devem-se usar os mesmos parâmetros de redação dos demais documentos oficiais, o que inclui linguagem adequada.$q$,$q$Quando da redação de e-mail que possa ser considerado um documento oficial, devem-se usar os mesmos parâmetros de redação dos demais documentos oficiais, o que inclui linguagem adequada.$q$,'C',1,'under_review',true,false,$q$Transcrição verbatim do caderno de provas Cargo 4 - Papiloscopista Policial Federal (PF 2021); gabarito conferido em Matriz_577_PF_004_00 (cargo Papiloscopista). Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
